        sz[a] += sz[b];
        sum[a] += sum[b];

        if (head[b] != -1) {
            if (head[a] == -1) {
                head[a] = head[b];
                tail[a] = tail[b];
            } else {
                nxt[tail[a]] = head[b];
                tail[a] = tail[b];
            }
        }

        return a;
    }

